const chatId = $('Catalog Webhook').first().json.body?.chatId || $('Catalog Webhook').first().json.chatId;
const products = $input.all().map(i=>i.json);

if (!products || products.length === 0) {
  return [{ json: { chatId, message: 'لم نجد منتجات مطابقة. جرّب: PS Plus، Xbox، Steam، Apple، Google Play' } }];
}

let text = 'نتائج البحث:\n\n';
products.slice(0,5).forEach((p,i) => {
  const price = p.price || p.regular_price || '?';
  text += `${i+1}. ${p.name}\n`;
  text += `   السعر: ${price} ر.س\n`;
  if (p.sku) text += `   SKU: ${p.sku}\n`;
  text += `   الرابط: ${p.permalink}\n\n`;
});

text += 'للشراء المباشر: https://neogen.store/shop/';

return [{ json: { chatId, message: text } }];
